# Function: Merge RPF length distribution tables generated by rpf_Check.
# Input: One or more *_length_distribution.txt files.
# Output: Merged RPF length distribution table.

import argparse
import glob
import math
import os
import sys
from pathlib import Path

import numpy as np
import pandas as pd

# matplotlib is imported lazily (AGG backend) only when a figure is drawn,
# keeping the merge workflow usable on headless servers.
matplotlib = None  # type: ignore[assignment]
plt = None  # type: ignore[assignment]

_PLOT_STYLE = {
    "font.family": "sans-serif",
    "font.sans-serif": ["Arial", "Helvetica", "Liberation Sans", "DejaVu Sans"],
    "mathtext.fontset": "dejavusans",
    "text.color": "black",
    "axes.edgecolor": "black",
    "axes.linewidth": 0.9,
    "axes.facecolor": "white",
    "axes.labelcolor": "black",
    "axes.labelsize": 12,
    "axes.titlesize": 14,
    "xtick.color": "black",
    "ytick.color": "black",
    "xtick.labelsize": 11,
    "ytick.labelsize": 11,
    "xtick.major.width": 0.9,
    "ytick.major.width": 0.9,
    "xtick.direction": "out",
    "ytick.direction": "out",
    "xtick.major.size": 3.5,
    "ytick.major.size": 3.5,
    "legend.frameon": True,
    "legend.edgecolor": "#BBBBBB",
    "legend.fancybox": False,
    "legend.fontsize": 11,
    "figure.facecolor": "white",
    "figure.dpi": 120,
    "savefig.dpi": 300,
}


def merge_length_args_parser():
    """Parse command-line arguments for length distribution merging."""
    parser = argparse.ArgumentParser(
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description="Merge RPF length distribution files generated by rpf_Check.",
    )

    input_group = parser.add_argument_group("Required arguments")
    input_group.add_argument(
        "-l",
        "--list",
        nargs="+",
        required=True,
        help=(
            "Input length distribution files or shell-style patterns. "
            "Examples: '*_length_distribution.txt' sample1_length_distribution.txt"
        ),
    )
    input_group.add_argument(
        "-o",
        dest="output",
        required=True,
        type=str,
        help="Output prefix.",
    )

    args = parser.parse_args()
    args.length_files = expand_input_files(args.list)

    print("list        :  " + ", ".join(args.length_files), flush=True)
    print("output      :  " + str(args.output), flush=True)

    return args


def expand_input_files(input_items):
    """Expand input files and glob patterns into a sorted unique file list.

    Parameters
    ----------
    input_items : list
        Input file names or shell-style glob patterns.

    Returns
    -------
    list
        Existing length distribution files.

    Workflow
    --------
    1. Expand shell-style glob patterns when they are quoted by the user.
    2. Keep normal file names unchanged.
    3. Remove duplicated paths while preserving sorted order.
    4. Fail early when no valid input file is found.
    """
    matched_files = []

    for item in input_items:
        expanded = glob.glob(item)
        if expanded:
            matched_files.extend(expanded)
        else:
            matched_files.append(item)

    unique_files = []
    seen_files = set()

    for file_name in sorted(matched_files):
        file_path = os.path.abspath(file_name)
        if file_path in seen_files:
            continue
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"Input length distribution file does not exist: {file_name}")
        unique_files.append(file_name)
        seen_files.add(file_path)

    if not unique_files:
        raise RuntimeError("No length distribution files were found.")

    return unique_files


def normalize_column_name(column_name):
    """Normalize a column name for flexible format detection."""
    return (
        str(column_name)
        .strip()
        .replace("\ufeff", "")
        .replace(" ", "")
        .replace("-", "")
        .replace("_", "")
        .lower()
    )


def infer_sample_name(length_file):
    """Infer sample name from a length distribution file name."""
    base_name = Path(length_file).name

    for suffix in (
        "_length_distribution.txt",
        ".length_distribution.txt",
        "_length_distribution.tsv",
        ".length_distribution.tsv",
    ):
        if base_name.endswith(suffix):
            return base_name[: -len(suffix)]

    if base_name.endswith(".txt") or base_name.endswith(".tsv"):
        return str(Path(base_name).with_suffix(""))

    return base_name


def find_column(column_map, candidate_names):
    """Find the first matching column from normalized candidate names."""
    for candidate in candidate_names:
        candidate_norm = normalize_column_name(candidate)
        if candidate_norm in column_map:
            return column_map[candidate_norm]
    return None


def import_length_file(length_file):
    """Read one length distribution file and return a canonical table.

    Parameters
    ----------
    length_file : str
        Input length distribution file.

    Returns
    -------
    pandas.DataFrame
        Canonical table with Length, Plus_Count, Minus_Count, and Total_Count.

    Workflow
    --------
    1. Read tab-delimited length distribution table.
    2. Detect old format: Length, Plus, Minus.
    3. Detect new format: Length, Plus, Minus, Total.
    4. Convert all count columns to numeric values.
    5. Sum duplicated length rows if present.
    """
    try:
        length_df = pd.read_csv(length_file, sep="\t", comment="#")
    except Exception as error:
        raise RuntimeError(f"Failed to read length distribution file: {length_file}. Error: {error}") from error

    if length_df.empty:
        raise RuntimeError(f"Length distribution file is empty: {length_file}")

    length_df = length_df.dropna(how="all")

    column_map = {
        normalize_column_name(column): column
        for column in length_df.columns
    }

    length_col = find_column(
        column_map,
        ["Length", "Read_Length", "RPF_Length", "RPFs_Length"],
    )
    plus_col = find_column(
        column_map,
        ["Plus", "Plus_Count", "PlusCount", "Forward", "Forward_Count"],
    )
    minus_col = find_column(
        column_map,
        ["Minus", "Minus_Count", "MinusCount", "Reverse", "Reverse_Count"],
    )
    total_col = find_column(
        column_map,
        ["Total", "Total_Count", "TotalCount", "Reads", "Read_Count"],
    )

    if length_col is None or plus_col is None or minus_col is None:
        if length_df.shape[1] >= 3:
            length_col = length_df.columns[0]
            plus_col = length_df.columns[1]
            minus_col = length_df.columns[2]
            total_col = length_df.columns[3] if length_df.shape[1] >= 4 else None
        else:
            raise RuntimeError(
                "Unrecognized length distribution format. "
                f"Expected at least 3 columns, but got {length_df.shape[1]} columns in {length_file}"
            )

    canonical_df = pd.DataFrame()
    canonical_df["Length"] = pd.to_numeric(length_df[length_col], errors="coerce")
    canonical_df["Plus_Count"] = pd.to_numeric(length_df[plus_col], errors="coerce").fillna(0)
    canonical_df["Minus_Count"] = pd.to_numeric(length_df[minus_col], errors="coerce").fillna(0)

    if total_col is not None:
        canonical_df["Total_Count"] = pd.to_numeric(length_df[total_col], errors="coerce")
    else:
        canonical_df["Total_Count"] = canonical_df["Plus_Count"] + canonical_df["Minus_Count"]

    canonical_df["Total_Count"] = canonical_df["Total_Count"].fillna(
        canonical_df["Plus_Count"] + canonical_df["Minus_Count"]
    )

    canonical_df = canonical_df.dropna(subset=["Length"])
    canonical_df["Length"] = canonical_df["Length"].astype(int)

    count_columns = ["Plus_Count", "Minus_Count", "Total_Count"]
    for column in count_columns:
        canonical_df[column] = canonical_df[column].round().astype(int)

    canonical_df = (
        canonical_df
        .groupby("Length", as_index=False, sort=True)[count_columns]
        .sum()
    )

    return canonical_df


def safe_ratio(count_series, denominator):
    """Calculate percentage ratio with zero-denominator protection."""
    if denominator <= 0:
        return pd.Series([0.0] * len(count_series), index=count_series.index)
    return count_series / denominator * 100.0


def process_length_files(length_file_list):
    """Merge length distribution files into one table.

    Parameters
    ----------
    length_file_list : list
        Input length distribution files.

    Returns
    -------
    pandas.DataFrame
        Merged length distribution table.

    Workflow
    --------
    1. Read each length distribution file.
    2. Standardize old and new column formats.
    3. Calculate plus, minus, and total ratios per sample.
    4. Merge all samples into a single long-format table.
    """
    merged_tables = []

    for input_order, length_file in enumerate(length_file_list):
        sample_name = infer_sample_name(length_file)
        length_df = import_length_file(length_file)

        plus_sum = int(length_df["Plus_Count"].sum())
        minus_sum = int(length_df["Minus_Count"].sum())
        total_sum = int(length_df["Total_Count"].sum())

        length_df["Plus_Ratio"] = safe_ratio(length_df["Plus_Count"], plus_sum)
        length_df["Minus_Ratio"] = safe_ratio(length_df["Minus_Count"], minus_sum)
        length_df["Total_Ratio"] = safe_ratio(length_df["Total_Count"], total_sum)
        length_df["Sample"] = sample_name
        length_df["_Input_Order"] = input_order

        merged_tables.append(length_df)

    if not merged_tables:
        raise RuntimeError("No valid length distribution table was loaded.")

    reads_length_df = pd.concat(merged_tables, axis=0, ignore_index=True)

    output_columns = [
        "Sample",
        "Length",
        "Plus_Count",
        "Minus_Count",
        "Total_Count",
        "Plus_Ratio",
        "Minus_Ratio",
        "Total_Ratio",
        "_Input_Order",
    ]
    reads_length_df = reads_length_df.loc[:, output_columns]
    reads_length_df = reads_length_df.sort_values(
        by=["_Input_Order", "Length"],
        ascending=[True, True],
    ).reset_index(drop=True)

    reads_length_df = reads_length_df.drop(columns=["_Input_Order"])

    return reads_length_df


def output_table(reads_length_df, output_prefix):
    """Write merged length distribution table.

    Parameters
    ----------
    reads_length_df : pandas.DataFrame
        Merged length distribution table.
    output_prefix : str
        Output prefix.

    Returns
    -------
    None
        The merged table is written to disk.
    """
    count_columns = ["Length", "Plus_Count", "Minus_Count", "Total_Count"]
    ratio_columns = ["Plus_Ratio", "Minus_Ratio", "Total_Ratio"]

    for column in count_columns:
        reads_length_df[column] = pd.to_numeric(reads_length_df[column], errors="raise").astype(int)

    for column in ratio_columns:
        reads_length_df[column] = pd.to_numeric(reads_length_df[column], errors="raise").round(4)

    output_file = output_prefix + "_length_distribution.txt"
    reads_length_df.to_csv(output_file, sep="\t", index=False)

    print(f"Output file :  {output_file}", flush=True)


def _ensure_plotting_backend():
    """Import matplotlib (AGG backend) on first figure drawing, in place."""
    global matplotlib, plt
    if plt is not None:
        return
    import matplotlib as _matplotlib

    _matplotlib.use("AGG")
    import matplotlib.pyplot as _plt

    matplotlib = _matplotlib
    plt = _plt


def _sample_line_colors(sample_count):
    """Sample distinguishable colors from the saturated ends of RdBu.

    The middle (white) part of RdBu is skipped so that every sample
    keeps a visible color, even when many samples are plotted together.

    Parameters
    ----------
    sample_count : int
        Number of sample lines to color.

    Returns
    -------
    numpy.ndarray
        RGBA colors, shape (sample_count, 4).
    """
    base_colors = matplotlib.cm.RdBu(np.linspace(0.0, 1.0, 256))
    # 0.0-0.45 and 0.55-1.0 of the RdBu scale, excluding the near-white middle
    left_side = base_colors[: int(256 * 0.45)]
    right_side = base_colors[int(256 * 0.55):]
    merged_colors = np.vstack([left_side, right_side])
    merged_cmap = matplotlib.colors.ListedColormap(merged_colors)
    return merged_cmap(np.linspace(0.0, 1.0, max(2, sample_count)))


def draw_dot_line_length_distr(reads_length_df, output_prefix):
    """Draw all samples' length distributions in one dot-line figure.

    Parameters
    ----------
    reads_length_df : pandas.DataFrame
        Merged length distribution table.
    output_prefix : str
        Output prefix.

    Returns
    -------
    list
        Output figure file names (PDF and PNG).

    Workflow
    --------
    1. Plot the total ratio of each sample against read length.
    2. Color all sample lines with the RdBu colormap.
    3. Save the figure as PDF and PNG files.
    """
    _ensure_plotting_backend()
    matplotlib.rcParams.update(_PLOT_STYLE)

    sample_names = reads_length_df["Sample"].unique().tolist()
    sample_count = len(sample_names)

    figure_width = 8.0
    figure_height = max(4.5, sample_count * 0.18 + 2.5)
    figure_height = min(figure_height, 12.0)

    fig, ax = plt.subplots(
        figsize=(figure_width, figure_height),
        constrained_layout=True,
    )
    ax.set_title("RPFs length distribution", fontsize=15)
    ax.set_xlabel("Read length (nt)", fontsize=13)
    ax.set_ylabel("Proportion (%)", fontsize=13)

    # sample distinguishable colors from the saturated ends of RdBu
    sample_colors = _sample_line_colors(sample_count)

    for color, sample_name in zip(sample_colors, sample_names):
        sample_df = reads_length_df.loc[
            reads_length_df["Sample"] == sample_name,
            ["Length", "Total_Ratio"],
        ].sort_values("Length")
        ax.plot(
            sample_df["Length"],
            sample_df["Total_Ratio"],
            color=color,
            linewidth=1.6,
            marker="o",
            markersize=4.0,
            label=sample_name,
        )

    length_min = int(reads_length_df["Length"].min())
    length_max = int(reads_length_df["Length"].max())
    tick_step = max(1, int(math.ceil((length_max - length_min) / 10)))
    ax.set_xticks(range(length_min, length_max + 1, tick_step))
    ax.tick_params(labelsize=11)

    # place the legend outside the axes, at the middle of the right side
    legend_columns = 1 if sample_count <= 10 else 2
    ax.legend(
        loc="center left",
        bbox_to_anchor=(1.01, 0.5),
        ncol=legend_columns,
        frameon=True,
        fontsize=11,
    )

    output_file_pdf = output_prefix + "_length_distribution_dotline.pdf"
    output_file_png = output_prefix + "_length_distribution_dotline.png"
    fig.savefig(output_file_pdf, bbox_inches="tight")
    fig.savefig(output_file_png, dpi=300, bbox_inches="tight")
    plt.close(fig)

    return [output_file_pdf, output_file_png]


def draw_heatmap_length_distr(reads_length_df, output_prefix):
    """Draw all samples' length distributions in one heatmap figure.

    Parameters
    ----------
    reads_length_df : pandas.DataFrame
        Merged length distribution table.
    output_prefix : str
        Output prefix.

    Returns
    -------
    list
        Output figure file names (PDF and PNG).

    Workflow
    --------
    1. Pivot the merged table into a sample-by-length matrix of total ratios.
    2. Fill missing lengths with zero.
    3. Plot the matrix with the Blues colormap.
    4. Save the figure as PDF and PNG files.
    """
    _ensure_plotting_backend()
    matplotlib.rcParams.update(_PLOT_STYLE)

    sample_names = reads_length_df["Sample"].unique().tolist()
    sample_count = len(sample_names)
    all_lengths = sorted(reads_length_df["Length"].unique().tolist())

    # pivot into a sample-by-length matrix of total ratios
    ratio_matrix = (
        reads_length_df.pivot_table(
            index="Sample",
            columns="Length",
            values="Total_Ratio",
            aggfunc="mean",
        )
        .reindex(index=sample_names)
        .reindex(columns=all_lengths, fill_value=0.0)
    )
    matrix_values = ratio_matrix.to_numpy(dtype=float)

    figure_width = max(8.0, len(all_lengths) * 0.32 + 3.0)
    figure_width = min(figure_width, 18.0)
    figure_height = max(4.0, sample_count * 0.32 + 1.8)
    figure_height = min(figure_height, 16.0)

    # Blues colormap: low values are light, high values are dark blue
    plot_cmap = matplotlib.colormaps["Blues"]

    fig, ax = plt.subplots(figsize=(figure_width, figure_height))
    image = ax.imshow(
        matrix_values,
        aspect="auto",
        interpolation="nearest",
        cmap=plot_cmap,
    )
    ax.set_title("RPFs length distribution", fontsize=15)
    ax.set_xlabel("Read length (nt)", fontsize=13)
    ax.set_ylabel("Sample", fontsize=13)

    # set x-axis ticks with readable step (no rotation)
    tick_step = max(1, int(math.ceil(len(all_lengths) / 10)))
    x_tick_indices = range(0, len(all_lengths), tick_step)
    x_tick_labels = [all_lengths[index] for index in x_tick_indices]
    ax.set_xticks(list(x_tick_indices))
    ax.set_xticklabels(x_tick_labels, rotation=0, ha="center", fontsize=11)

    # set y-axis ticks with sample names
    if sample_count <= 60:
        ax.set_yticks(range(sample_count))
        ax.set_yticklabels(sample_names, fontsize=11)
    else:
        y_tick_indices = np.linspace(0, sample_count - 1, 20, dtype=int)
        ax.set_yticks(y_tick_indices)
        ax.set_yticklabels([sample_names[index] for index in y_tick_indices], fontsize=10)

    colorbar = fig.colorbar(image, ax=ax, shrink=0.8, pad=0.02)
    colorbar.set_label("Proportion (%)", fontsize=12)
    colorbar.ax.tick_params(labelsize=10)

    output_file_pdf = output_prefix + "_length_distribution_heatmap.pdf"
    output_file_png = output_prefix + "_length_distribution_heatmap.png"
    fig.savefig(output_file_pdf, bbox_inches="tight")
    fig.savefig(output_file_png, dpi=300, bbox_inches="tight")
    plt.close(fig)

    return [output_file_pdf, output_file_png]


def output_plot(reads_length_df, output_prefix):
    """Draw the merged length distribution figures.

    Parameters
    ----------
    reads_length_df : pandas.DataFrame
        Merged length distribution table.
    output_prefix : str
        Output prefix.

    Returns
    -------
    None
        The merged length distribution figures are written to disk.
    """
    dot_line_files = draw_dot_line_length_distr(reads_length_df, output_prefix)
    heatmap_files = draw_heatmap_length_distr(reads_length_df, output_prefix)

    for output_file in dot_line_files + heatmap_files:
        print(f"Output file :  {output_file}", flush=True)


def main():
    """Run the length distribution merging workflow."""
    print("Step1: Checking the input arguments.", flush=True)
    args = merge_length_args_parser()

    print("Step2: Import the length distribution files.", flush=True)
    reads_length_df = process_length_files(args.length_files)

    print("Step3: Output the merged length distribution table.", flush=True)
    output_table(reads_length_df, args.output)

    print("Step4: Draw the length distribution figures.", flush=True)
    output_plot(reads_length_df, args.output)

    print("All done.", flush=True)


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print(f"Error: {error}", file=sys.stderr, flush=True)
        sys.exit(1)
